/* World country outlines, converted from the client-supplied world map SVG
   (Miller-style projection), pre-projected into an 800×430 viewBox. Only the
   countries we highlight carry an ISO 3166-1 numeric `iso`; the rest are plain land.
   Regenerate rather than hand-edit. */
export const MAP_WIDTH = 800;
export const MAP_HEIGHT = 430;

/* [lon, lat] -> [x, y] in the same space (fitted to the source artwork). */
export function project([lon, lat]) {
  const my = 1.25 * Math.log(Math.tan(Math.PI / 4 + (0.4 * lat * Math.PI) / 180));
  return [(58.4445 + 0.32333 * lon - 2) * 6.722689075630252, (54.4522 - 20.1105 * my - 13) * 6.722689075630252];
}

